def de_bruijn(k, n):
    alphabet = list(range(k))
    sequence = []
    def db(t, p):
        if t > n:
            if n % p == 0:
                sequence.extend(a[1:p+1])
        else:
            a[t] = a[t - p]
            db(t + 1, p)
            for j in alphabet:
                if j > a[t - p]:
                    a[t] = j
                    db(t + 1, t)
    a = [0] * (n + 1)
    db(1, 1)
    return sequence

def verify_de_bruijn(seq, k, n):
    L = len(seq)
    if L != k**n:
        return False, f"Wrong length: {L} != {k**n}"
    seen = set()
    for i in range(L):
        ngram = tuple(seq[(i + j) % L] for j in range(n))
        if ngram in seen:
            return False, f"Duplicate n-gram at position {i}: {ngram}"
        seen.add(ngram)
    if len(seen) != k**n:
        return False, f"Only {len(seen)} unique n-grams"
    return True, "Valid!"

