import random
from collections import deque

def bfs_dist(adj, u, v, n):
    """BFS distance from u to v"""
    dist = [-1] * n
    dist[u] = 0
    q = deque([u])
    while q:
        x = q.popleft()
        if x == v:
            return dist[v]
        for nb in adj[x]:
            if dist[nb] == -1:
                dist[nb] = dist[x] + 1
                q.append(nb)
    return float('inf')

def compute_girth(adj, n):
    """Compute girth of graph"""
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        q = deque([(start, -1)])
        while q:
            u, parent = q.popleft()
            for v in adj[u]:
                if v == parent:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append((v, u))
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def check_3colorable(adj, n):
    """Check if graph is 3-colorable using backtracking"""
    color = [-1] * n
    def bt(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if color[u] != -1:
                used.add(color[u])
        for c in range(3):
            if c not in used:
                color[v] = c
                if bt(v+1):
                    return True
                color[v] = -1
        return False
    return bt(0)

