def lcf_graph(n, lcf_list):
    """Construct graph from LCF notation"""
    edges = set()
    for i in range(n):
        u, v = i, (i+1) % n
        if u > v: u, v = v, u
        edges.add((u, v))
    period = len(lcf_list)
    for i in range(n):
        offset = lcf_list[i % period]
        j = (i + offset) % n
        u, v = min(i, j), max(i, j)
        edges.add((u, v))
    return list(edges)

