def solve():
    grid = [[-1]*n for _ in range(n)]

    # Set diagonal
    for i in range(n):
        grid[i][i] = i

    # Track row/col usage
    row_used = [set([i]) for i in range(n)]
    col_used = [set([i]) for i in range(n)]

    # Get cells to fill (non-diagonal), ordered carefully
    cells = [(i, j) for i in range(n) for j in range(n) if i != j]

