        # Check all QG3 constraints where all three values are known
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a != -1 and b != -1 and grid[a][b] != -1:
                    if grid[a][b] != i:
                        return False
        return True

